const Icon = () => <Button
    variant="default"
    size="icon"
    disabled={false}
    onClick={fn()}
    aria-label="Add item"><Plus /></Button>;

const WithIcon = () => <Button variant="default" size="default" disabled={false} onClick={fn()}>(<>Continue
              <ArrowRight data-icon="inline-end" />
    </>)</Button>;

const Loading = () => <Button variant="default" size="default" disabled onClick={fn()} aria-busy>(<>
      <Loader2 className="animate-spin" data-icon="inline-start" />Saving
            </>)</Button>;

